# General Information: R.A. 6713 (Code of Conduct and Ethical Standards for Public Officials and
# Employees, 1989), peace and human rights, and environment management and protection.
# Laws named by number and year only; no officeholders, fines or current events. Key first.
ITEMS = [
    # ---------- Practice Test 1 (Professional) ----------
    S(1, 1, "R.A. 6713", "Within how many working days from receipt must public officials and employees respond to letters and requests from the public under R.A. 6713?",
      ["15 working days", "5 working days", "30 working days", "45 working days"],
      "Section 5(a) of R.A. 6713 requires a response within 15 working days from receipt, stating the action taken. 45 working days is the deadline for heads of office to submit annual performance reports."),
    S(1, 2, "R.A. 6713", "Under R.A. 6713, the Statement of Assets, Liabilities and Net Worth (SALN) must be filed every year on or before:",
      ["April 30", "January 31", "June 30", "December 31"],
      "Section 8 requires the SALN within 30 days after assuming office, on or before April 30 of every year, and within 30 days after leaving the service."),
    S(1, 2, "R.A. 6713", "Which norm of conduct in R.A. 6713 requires public servants to serve everyone without unfair discrimination, regardless of party affiliation?",
      ["Political neutrality", "Professionalism", "Simple living", "Commitment to democracy"],
      "Section 4(d), political neutrality, requires service to everyone without unfair discrimination regardless of party affiliation or preference."),
    S(1, 2, "R.A. 6713", "Under R.A. 6713, the prohibited acts in Section 7 continue to apply for how long after an official resigns, retires or leaves public office?",
      ["One year", "Six months", "Two years", "Three years"],
      "Section 7 says its prohibitions continue to apply for one year after resignation, retirement or separation from public office."),
    S(1, 3, "R.A. 6713", "Under R.A. 6713, \"relatives\" are persons related to the official within which degree of consanguinity or affinity?",
      ["Fourth civil degree", "Second civil degree", "Third civil degree", "Sixth civil degree"],
      "Section 3(k) defines relatives as persons within the fourth civil degree of consanguinity or affinity, including bilas, inso and balae."),
    S(1, 2, "Human rights", "Which body does the 1987 Constitution create to investigate violations of civil and political rights?",
      ["Commission on Human Rights", "Commission on Audit", "Civil Service Commission", "Commission on Elections"],
      "Article XIII, Section 17 creates the independent Commission on Human Rights, which investigates all forms of human rights violations involving civil and political rights."),
    S(1, 3, "Human rights", "The Universal Declaration of Human Rights was adopted by the United Nations General Assembly in what year?",
      ["1948", "1945", "1966", "1987"],
      "The UDHR was adopted on December 10, 1948, which is why Human Rights Day is marked on December 10. The UN itself was founded in 1945, and the two international covenants date from 1966."),
    S(1, 3, "Peace process", "Which law created the Bangsamoro Autonomous Region in Muslim Mindanao (BARMM)?",
      ["R.A. 11054", "R.A. 9262", "R.A. 9003", "R.A. 6734"],
      "R.A. 11054 of 2018, the Bangsamoro Organic Law, created BARMM after a plebiscite in 2019, replacing the ARMM that R.A. 6734 had set up in 1989."),
    S(1, 2, "Environment", "Which law requires waste to be segregated at the source and bans open dumpsites?",
      ["Ecological Solid Waste Management Act", "Philippine Clean Air Act", "Philippine Clean Water Act", "Climate Change Act"],
      "R.A. 9003 of 2000, the Ecological Solid Waste Management Act, requires segregation at source, materials recovery facilities and the closure of open dumpsites."),
    S(1, 3, "Environment", "Which judicial writ may be filed to protect the constitutional right to a balanced and healthful ecology when the damage affects two or more cities or provinces?",
      ["Writ of kalikasan", "Writ of amparo", "Writ of habeas data", "Writ of habeas corpus"],
      "The writ of kalikasan, under the Supreme Court's 2010 Rules of Procedure for Environmental Cases, covers environmental damage of such magnitude that it harms life, health or property in two or more cities or provinces."),

    # ---------- Practice Test 2 (Subprofessional) ----------
    S(2, 1, "R.A. 6713", "R.A. 6713 is known as the:",
      ["Code of Conduct and Ethical Standards", "Anti-Graft and Corrupt Practices Act", "Government Auditing Code of the Philippines", "Local Government Code"],
      "R.A. 6713 of 1989 is the Code of Conduct and Ethical Standards for Public Officials and Employees. The Anti-Graft and Corrupt Practices Act is R.A. 3019 and the Local Government Code is R.A. 7160. The Government Auditing Code is a 1978 decree, not a republic act."),
    S(2, 1, "R.A. 6713", "Which norm of conduct in R.A. 6713 says public servants should lead modest lives and avoid extravagant display of wealth?",
      ["Simple living", "Professionalism", "Political neutrality", "Responsiveness to the public"],
      "Section 4(h), simple living, requires modest lives appropriate to one's position and income, with no extravagant or ostentatious display of wealth."),
    S(2, 2, "R.A. 6713", "Which norm of conduct in R.A. 6713 includes promoting the use of locally produced goods, resources and technology?",
      ["Nationalism and patriotism", "Commitment to public interest", "Justness and sincerity", "Commitment to democracy"],
      "Section 4(f), nationalism and patriotism, calls for loyalty to the Republic and the Filipino people and promoting locally produced goods, resources and technology."),
    S(2, 2, "R.A. 6713", "Under R.A. 6713, which government agency has the primary responsibility for administering and enforcing the Code?",
      ["Civil Service Commission", "Commission on Audit", "Department of Justice", "Commission on Elections"],
      "Section 12 gives the Civil Service Commission primary responsibility for administering and enforcing the Act and authority to issue its rules."),
    S(2, 2, "R.A. 6713", "R.A. 6713 says documents should, as far as practicable, need no more than how many signatories?",
      ["Three", "Two", "Five", "Seven"],
      "Section 5(c) requires documents to be processed within a reasonable time and, as far as practicable, to carry not more than three signatories."),
    S(2, 1, "Human rights", "Human Rights Day is observed every year on:",
      ["December 10", "June 12", "August 21", "November 30"],
      "December 10 marks the adoption of the Universal Declaration of Human Rights in 1948. June 12 is Independence Day and November 30 is Bonifacio Day."),
    S(2, 2, "Human rights", "Which law protects women and their children from physical, sexual, psychological and economic abuse by a partner?",
      ["Anti-VAWC Act of 2004", "Safe Spaces Act of 2019", "Anti-Torture Act of 2009", "Anti-Trafficking Act of 2003"],
      "R.A. 9262, the Anti-Violence Against Women and Their Children (Anti-VAWC) Act of 2004, covers physical, sexual, psychological and economic abuse by a partner or former partner. The Safe Spaces Act covers gender-based harassment in streets, workplaces and online."),
    S(2, 2, "Peace and human rights", "The Philippines is a party to the United Nations convention that protects the rights of every person below 18 years of age. What is it called?",
      ["Convention on the Rights of the Child", "Universal Declaration of Human Rights", "Geneva Convention on Refugees", "Charter of the United Nations"],
      "The Convention on the Rights of the Child (1989) covers every person below 18. The Philippines ratified it in 1990."),
    S(2, 1, "Environment", "Which law sets national air quality standards and bans the incineration of municipal, medical and hazardous waste that gives off toxic fumes?",
      ["Philippine Clean Air Act of 1999", "Philippine Clean Water Act of 2004", "Philippine Fisheries Code of 1998", "Climate Change Act of 2009"],
      "R.A. 8749, the Philippine Clean Air Act of 1999, sets air quality standards and bans incinerating municipal, biomedical and hazardous waste in a way that emits poisonous and toxic fumes. Open burning of solid waste is also banned under R.A. 9003."),
    S(2, 1, "Environment", "Which agency is the lead government agency for environment and natural resources?",
      ["DENR", "DILG", "DPWH", "DOTr"],
      "The Department of Environment and Natural Resources (DENR) manages and protects the country's environment and natural resources. DILG oversees local governments, DPWH public works and DOTr transportation."),

    # ---------- Drill only ----------
    S(0, 2, "R.A. 6713", "Under R.A. 6713, an official who has a conflict of interest must divest his or her shares in a private business within how many days of assuming office?",
      ["60 days", "15 days", "30 days", "45 days"],
      "Section 9 requires resignation from any position in the private business within 30 days and divestment of shareholdings or interest within 60 days of assuming office."),
    S(0, 2, "Environment", "Which law created the Climate Change Commission and set up the national framework for climate change action?",
      ["Climate Change Act of 2009", "Philippine Clean Air Act of 1999", "Philippine Mining Act of 1995", "Ecological Solid Waste Management Act of 2000"],
      "R.A. 9729, the Climate Change Act of 2009, created the Climate Change Commission to coordinate climate policy and plans."),
    S(0, 3, "Disaster risk", "Which law created the National Disaster Risk Reduction and Management Council (NDRRMC)?",
      ["R.A. 10121", "R.A. 9729", "R.A. 8749", "R.A. 9275"],
      "R.A. 10121, the Philippine Disaster Risk Reduction and Management Act of 2010, created the NDRRMC. R.A. 9729 is the Climate Change Act, R.A. 8749 the Clean Air Act and R.A. 9275 the Clean Water Act."),
]
